// This code has been fully generated by an AI.
//
// Pure helpers for the heatmap: filter state → MapLibre filter expression and
// summary. No DOM access, so the module can be tested with node --test.

const DAY = 86400;

/**
 * Local-time range [from, to) in Unix seconds for a period selection.
 * period: "all" | "12m" | "<year>" | "custom" (uses fromDate/toDate,
 * YYYY-MM-DD, toDate inclusive). now: local wall clock as Unix seconds.
 */
export function periodRange({ period, fromDate, toDate }, now) {
  if (/^\d{4}$/.test(period ?? "")) {
    const y = Number(period);
    return [Date.UTC(y, 0, 1) / 1000, Date.UTC(y + 1, 0, 1) / 1000];
  }
  if (period === "12m") return [now - 365 * DAY, Infinity];
  if (period === "custom") {
    const from = fromDate ? Date.parse(fromDate + "T00:00:00Z") / 1000 : -Infinity;
    const to = toDate ? Date.parse(toDate + "T00:00:00Z") / 1000 + DAY : Infinity;
    return [Number.isNaN(from) ? -Infinity : from, Number.isNaN(to) ? Infinity : to];
  }
  return [-Infinity, Infinity];
}

/** MapLibre filter expression for the selected categories and period. */
export function filterExpression(state, now) {
  const [from, to] = periodRange(state, now);
  const expr = ["all", ["in", ["get", "cat"], ["literal", [...state.categories]]]];
  if (Number.isFinite(from)) expr.push([">=", ["get", "t"], from]);
  if (Number.isFinite(to)) expr.push(["<", ["get", "t"], to]);
  return expr;
}

/** Same filter as filterExpression, evaluated in JavaScript. */
export function matches(feature, state, now) {
  const [from, to] = periodRange(state, now);
  const p = feature.properties;
  return state.categories.includes(p.cat) && p.t >= from && p.t < to;
}

/** Count and distance of the features matching the state. */
export function summarize(features, state, now) {
  let count = 0;
  let km = 0;
  for (const f of features) {
    if (matches(f, state, now)) {
      count++;
      km += f.properties.km;
    }
  }
  return { count, km: Math.round(km) };
}

/** Current local wall clock as Unix seconds (same convention as feature.t). */
export function localNow(date = new Date()) {
  return Math.floor(date.getTime() / 1000) - date.getTimezoneOffset() * 60;
}

/** Line color expression: one heat color or a color per category. */
export function colorExpression(mode, categories) {
  if (mode !== "category") return "#ff5722";
  const expr = ["match", ["get", "cat"]];
  for (const c of categories) expr.push(c.id, c.color);
  expr.push("#888");
  return expr;
}
